INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'External Iliac Vein (EIV)', 'Curvilinear 2–5 MHz; patient supine', '[{"id": "venous_eiv_0", "label": "Transverse compression at inguinal ligament level", "detail": "Compress every 2 cm along the vessel course", "critical": true}, {"id": "venous_eiv_1", "label": "Longitudinal color Doppler — confirm flow, respiratory phasicity", "detail": "", "critical": false}, {"id": "venous_eiv_2", "label": "Spectral Doppler — phasic waveform with respiration", "detail": "Loss of phasicity suggests proximal obstruction (iliac or IVC)", "critical": false}]', 0, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'Common Femoral Vein (CFV)', 'Linear 5–12 MHz; patient supine, hip externally rotated', '[{"id": "venous_cfv_0", "label": "Transverse compression at inguinal crease", "detail": "Vessel should fully collapse with gentle probe pressure", "critical": true}, {"id": "venous_cfv_1", "label": "Longitudinal color Doppler — augmentation with calf squeeze", "detail": "", "critical": false}, {"id": "venous_cfv_2", "label": "Spectral Doppler — phasic waveform, Valsalva response", "detail": "", "critical": false}, {"id": "venous_cfv_3", "label": "Saphenofemoral junction (SFJ) — assess for reflux if indicated", "detail": ">0.5 s reflux on Valsalva = significant", "critical": false}]', 1, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'Femoral Vein (FV) / Superficial Femoral Vein', 'Linear 5–12 MHz; patient supine', '[{"id": "venous_fv_0", "label": "Compression every 2–3 cm from CFV to adductor canal", "detail": "", "critical": true}, {"id": "venous_fv_1", "label": "Color Doppler throughout — note any filling defects", "detail": "", "critical": false}, {"id": "venous_fv_2", "label": "Spectral Doppler at mid-thigh level", "detail": "", "critical": false}]', 2, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'Popliteal Vein (PopV)', 'Linear 5–12 MHz; patient prone or lateral decubitus', '[{"id": "venous_pop_0", "label": "Transverse compression at popliteal fossa", "detail": "", "critical": true}, {"id": "venous_pop_1", "label": "Color Doppler — augmentation with foot dorsiflexion", "detail": "", "critical": false}, {"id": "venous_pop_2", "label": "Identify popliteal artery (pulsatile) adjacent to vein", "detail": "", "critical": false}]', 3, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'Calf Veins (Tibial / Peroneal)', 'Linear 5–12 MHz; patient prone or lateral decubitus', '[{"id": "venous_calf_0", "label": "Anterior tibial, posterior tibial, and peroneal veins — compression bilaterally", "detail": "Calf DVT extends to popliteal in ~20% — follow-up in 5–7 days if isolated", "critical": false}, {"id": "venous_calf_1", "label": "Gastrocnemius and soleal sinuses — assess for muscular vein thrombosis", "detail": "", "critical": false}]', 4, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('venous', 'Great Saphenous Vein (GSV)', 'Linear 5–12 MHz; patient supine or standing', '[{"id": "venous_gsv_0", "label": "GSV diameter at SFJ and mid-thigh — document for ablation planning", "detail": ">3 mm at SFJ with reflux = significant insufficiency", "critical": false}, {"id": "venous_gsv_1", "label": "Reflux assessment: Valsalva at SFJ; cuff deflation at thigh/calf", "detail": ">0.5 s reflux = pathologic", "critical": false}, {"id": "venous_gsv_2", "label": "Varicosities — map distribution and perforator connections", "detail": "", "critical": false}]', 5, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('arterial', 'Duplex Ultrasound', 'Linear 5–12 MHz — follow artery from groin to ankle; color Doppler throughout', '[{"id": "art_dup_0", "label": "Common femoral artery (CFA) — PSV and waveform morphology", "detail": "Normal CFA: triphasic waveform. Blunted monophasic = proximal (aortoiliac) disease.", "critical": true}, {"id": "art_dup_1", "label": "Superficial femoral artery (SFA) — PSV at origin, mid, and distal segments", "detail": "SFA is the most common site for PAD. PSV ratio >2.0 across stenosis = ≥50% stenosis.", "critical": true}, {"id": "art_dup_2", "label": "Popliteal artery — PSV and waveform", "detail": "Popliteal aneurysm: diameter >1.5 cm. Bilateral in 50%; associated with AAA in 30%.", "critical": true}, {"id": "art_dup_3", "label": "Tibial arteries (anterior, posterior, peroneal) — patency and PSV", "detail": "Assess all 3 tibial arteries for occlusion or stenosis", "critical": true}, {"id": "art_dup_4", "label": "PSV ratio at stenotic segments (>2.0 = ≥50%; >4.0 = ≥75%)", "detail": "", "critical": true}, {"id": "art_dup_5", "label": "Doppler angle consistency (≤60°)", "detail": "", "critical": true}]', 0, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('arterial', 'Segmental Limb Pressures', 'Pneumatic cuffs at upper thigh, lower thigh, calf, ankle — CW Doppler probe', '[{"id": "art_slp_0", "label": "Ankle-Brachial Index (ABI) — bilateral", "detail": "Normal 1.00–1.40; mild PAD 0.71–0.90; moderate 0.41–0.70; severe ≤0.40; >1.40 = non-compressible", "critical": true}, {"id": "art_slp_1", "label": "Segmental pressure measurements (upper thigh, lower thigh, calf, ankle)", "detail": "Gradient >20 mmHg between adjacent segments = hemodynamically significant disease", "critical": true}, {"id": "art_slp_2", "label": "Toe-Brachial Index (TBI) when ABI >1.40", "detail": "TBI = toe pressure ÷ brachial pressure; normal ≥0.70", "critical": true}]', 1, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('arterial', 'Pulse Volume Recordings (PVRs)', 'Pneumatic cuffs at upper thigh, lower thigh, calf, ankle, metatarsals', '[{"id": "art_pvr_0", "label": "PVR waveform morphology at each level", "detail": "Normal: sharp upstroke, narrow systolic peak, dicrotic notch. Abnormal: rounded peak, absent dicrotic notch.", "critical": true}, {"id": "art_pvr_1", "label": "Global tissue perfusion assessment", "detail": "PVRs reflect global volume changes; useful in patients with calcified vessels", "critical": true}]', 2, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);
INSERT INTO navigatorOverrides (moduleKey, sectionName, probe, items, displayOrder, createdAt, updatedAt) VALUES ('arterial', 'Ultrasound-Guided Biopsy / FNA', 'High-frequency linear 10–18 MHz; sterile technique', '[{"id": "art_bx_0", "label": "Pre-procedure: confirm target, review coagulation status", "detail": "", "critical": true}, {"id": "art_bx_1", "label": "Real-time needle visualization — in-plane technique preferred", "detail": "", "critical": true}, {"id": "art_bx_2", "label": "Post-procedure: assess for hematoma, confirm hemostasis", "detail": "", "critical": true}, {"id": "art_bx_3", "label": "Document needle tip position relative to target", "detail": "", "critical": true}]', 3, UNIX_TIMESTAMP()*1000, UNIX_TIMESTAMP()*1000) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), displayOrder=VALUES(displayOrder), updatedAt=VALUES(updatedAt);

